<?php
require __DIR__ . '/includes/bootstrap.php';
$rows=query("SELECT c.code AS class_code,s.code,s.name,COUNT(a.session_id) AS total,COALESCE(SUM(a.status='present'),0) AS present,COALESCE(SUM(a.status='absent'),0) AS absent,COALESCE(SUM(a.status='late'),0) AS late,COALESCE(SUM(a.status='unmarked'),0) AS unmarked FROM students s JOIN classes c ON c.id=s.class_id LEFT JOIN attendance a ON a.student_id=s.id GROUP BY s.id,c.code,s.code,s.name ORDER BY c.code,s.code")->fetchAll();
$totals=['present'=>0,'absent'=>0,'late'=>0,'unmarked'=>0]; foreach ($rows as $r) foreach ($totals as $k=>$v) $totals[$k]+=(int)$r[$k];
page_start('Thống kê chuyên cần','statistics.php');
?>
<section class="metrics"><?php foreach ($totals as $k=>$v): ?><article class="metric"><span><?= status_label($k) ?></span><strong><?= $v ?></strong></article><?php endforeach; ?></section><section class="panel"><h2>Chuyên cần theo sinh viên</h2><p class="muted">Tỷ lệ tham dự = (có mặt + đi muộn) / số lượt đã điểm danh × 100%. Không tính lượt chưa điểm danh. Bao gồm sinh viên đã ngừng theo dõi.</p><div class="table-scroll"><table><thead><tr><th>Sinh viên</th><th>Lớp</th><th>Tổng buổi</th><th>Có mặt</th><th>Vắng</th><th>Muộn</th><th>Chưa ghi</th><th>Tham dự</th></tr></thead><tbody><?php if (!$rows) echo '<tr><td colspan="8" class="empty">Chưa có dữ liệu thống kê.</td></tr>'; foreach ($rows as $r): $marked=(int)$r['total']-(int)$r['unmarked']; ?><tr><td><strong><?= e($r['name']) ?></strong><br><small><?= e($r['code']) ?></small></td><td><?= e($r['class_code']) ?></td><td><?= e($r['total']) ?></td><td><?= e($r['present']) ?></td><td><?= e($r['absent']) ?></td><td><?= e($r['late']) ?></td><td><?= e($r['unmarked']) ?></td><td><span class="badge present"><?= $marked ? round(((int)$r['present']+(int)$r['late'])/$marked*100,1).'%' : '—' ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><?php page_end(); ?>
